// contentFactory.js
export const contentFactory = (mode, token) => {
  const API_BASE = "http://127.0.0.1:8000/api";

  const createFormData = (articleData) => {
    const formData = new FormData();
    const title = articleData.title || "untitled";

    formData.append(
      "slug",
      title.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + Date.now()
    );
    formData.append("title", title);
    formData.append("content", articleData.content || "");
    formData.append("excerpt", articleData.excerpt || "");
    formData.append("category", articleData.category || "News");
    formData.append("is_premium", articleData.is_premium ? "true" : "false");
    formData.append("type", articleData.type || "standard");

    if (articleData.channel) formData.append("channel", articleData.channel);
    if (articleData.image) formData.append("image", articleData.image);

    return formData;
  };

  return async (articleData) => {
    const formData = createFormData(articleData);

    const res = await fetch(`${API_BASE}/articles/`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });

    if (!res.ok) {
      const errData = await res.json();
      console.error("Помилка створення статті:", errData);
      throw new Error(
        mode === "channel"
          ? "Не вдалося створити статтю для каналу"
          : "Не вдалося створити стандартну статтю"
      );
    }
    return await res.json();
  };
};
